/* Infrastructure service catalog, project portal, approval inbox and persistent basket. */
'use strict';

const SelectionBasket = {
  async add(resourceKind, hostId, resourceRef, displayName, compatibility = {}) {
    const basket = await Api.addSelfServiceBasketItem({ resourceKind, hostId, resourceRef, displayName, compatibility });
    Toast.success(`${displayName} added to basket (${basket.items.length})`);
    document.dispatchEvent(new CustomEvent('self-service:basket', { detail: basket }));
    return basket;
  },
};
globalThis.SelectionBasket = SelectionBasket;

const SelfServicePage = {
  _container: null, _tab: 'catalog', _data: {}, _projectId: null, _deepLink: null, _keyboardHandler: null,
  _route(params) {
    const parts = String(params?.id || '').split('/').filter(Boolean);
    if (parts[0] === 'project' && /^\d+$/.test(parts[1] || '')) { this._projectId = Number(parts[1]); this._tab = 'project'; }
    if (parts[0] === 'request' && /^\d+$/.test(parts[1] || '')) { this._deepLink = { requestId: Number(parts[1]) }; this._tab = 'requests'; }
    if (parts[0] === 'catalog' && parts[1]) { this._deepLink = { catalogSlug: decodeURIComponent(parts[1]) }; this._tab = 'catalog'; }
  },
  async render(container, params = {}) {
    this._container = container; this._route(params);
    container.innerHTML = '<div class="page-loading"><i class="fas fa-spinner fa-spin"></i></div>';
    try {
      const admin = App.user?.role === 'admin'; const approver = ['admin', 'operator'].includes(App.user?.role);
      const [catalog, projects, requests, basket, inbox, branding, incidents, feedback] = await Promise.all([
        Api.getSelfServiceCatalog(admin), Api.listGovernanceProjects(), Api.listSelfServiceRequests(), Api.getSelfServiceBasket(),
        approver ? Api.getSelfServiceApprovalInbox().catch(() => ({ requests: [] })) : Promise.resolve({ requests: [] }),
        Api.getSelfServiceBranding(), Api.getSelfServiceIncidents(), Api.getSelfServiceFeedbackPreference(),
      ]);
      this._data = { catalog: catalog.items || [], projects: projects.projects || [], requests: requests.requests || [], basket,
        inbox: inbox.requests || [], dashboard: null, capacity: null, quotaRequests: [], recommendations: [],
        branding: branding.branding, incidents: incidents.incidents || [], feedback, help: null };
      if (!this._projectId && this._data.projects.length) this._projectId = this._data.projects[0].id;
      if (this._projectId) await this._loadProjectContext();
      this._applyBranding();
      this._paint();
      if (this._deepLink?.requestId) setTimeout(() => this._timeline(this._deepLink.requestId), 0);
      if (this._deepLink?.catalogSlug) {
        const item = this._data.catalog.find(entry => entry.slug === this._deepLink.catalogSlug);
        if (item) setTimeout(() => this._request(item), 0);
      }
    } catch (error) { container.innerHTML = `<div class="empty-state"><i class="fas fa-store"></i><h3>Infrastructure Self-Service</h3><p>${Utils.escapeHtml(error.message)}</p></div>`; }
  },
  async _loadProjectContext() {
    const [dashboard, capacity, quotaRequests, recommendations, branding] = await Promise.all([
      Api.getSelfServiceProjectDashboard(this._projectId), Api.getProjectCapacity(this._projectId), Api.listQuotaRequests(this._projectId),
      Api.getSelfServiceRecommendations(this._projectId), Api.getSelfServiceBranding(this._projectId),
    ]);
    Object.assign(this._data, { dashboard, capacity, quotaRequests: quotaRequests.requests || [],
      recommendations: recommendations.recommendations || [], branding: branding.branding });
  },
  _applyBranding() {
    const branding = this._data.branding || {}; const color = /^#[0-9a-f]{6}$/i.test(branding.accentColor || '') ? branding.accentColor : '#4f8cff';
    this._container?.style.setProperty('--ss-accent', color);
  },
  async _refresh() { await this.render(this._container); },
  _t(key, fallback) { const value = globalThis.i18n?.t(`selfService.${key}`); return !value || value === `selfService.${key}` ? fallback : value; },
  _announce(message) { const live = this._container?.querySelector('#ss-live'); if (live) live.textContent = message; },
  _badge(state) { return ['validated', 'approved'].includes(state) ? 'badge-success' : ['failed', 'rejected', 'expired'].includes(state) ? 'badge-danger' : state === 'requested' ? 'badge-warning' : 'badge-secondary'; },
  _money(cost) { return cost?.amount == null ? '—' : `${Number(cost.amount).toFixed(2)} ${Utils.escapeHtml(cost.currency || 'EUR')} / ${Utils.escapeHtml(cost.period || 'month')}`; },
  _empty(message, cols) { return `<tr><td colspan="${cols}" class="text-muted" style="text-align:center;padding:24px">${Utils.escapeHtml(message)}</td></tr>`; },
  _stat(icon, label, value, detail = '') { return `<div class="info-item"><div class="info-label"><i class="fas ${icon}" style="margin-right:5px"></i>${label}</div><div class="info-value">${value}</div>${detail ? `<div class="text-xs text-muted">${detail}</div>` : ''}</div>`; },
  _tabBtn(tab, icon, label) { const active = this._tab === tab; return `<button type="button" role="tab" aria-selected="${active}" tabindex="${active ? 0 : -1}" class="tab-btn ${active ? 'active' : ''}" data-ss-tab="${tab}"><i class="fas ${icon}" aria-hidden="true"></i> ${label}</button>`; },
  _paint() {
    const projectOptions = this._data.projects.map(project => `<option value="${project.id}"${project.id === this._projectId ? ' selected' : ''}>${Utils.escapeHtml(project.name)}</option>`).join('');
    const branding = this._data.branding || {}; const title = Utils.escapeHtml(branding.displayName || this._t('title', 'Infrastructure Self-Service'));
    this._container.innerHTML = `<div class="self-service-portal"><div id="ss-live" class="sr-only" aria-live="polite" aria-atomic="true"></div><div class="page-header"><div class="ss-brand">${branding.logoUrl ? `<img class="ss-brand-logo" src="${Utils.escapeHtml(branding.logoUrl)}" alt="">` : '<i class="fas fa-store ss-brand-icon" aria-hidden="true"></i>'}<div><h1 class="page-title">${title}</h1><p class="page-subtitle">Curated offerings, policy-scoped project actions and auditable fulfillment.</p></div></div><div class="page-actions">${projectOptions ? `<label class="sr-only" for="ss-project">Project</label><select id="ss-project" class="form-control" style="min-width:220px">${projectOptions}</select>` : ''}${App.user?.role === 'admin' ? '<button type="button" class="btn btn-secondary" id="ss-branding"><i class="fas fa-palette" aria-hidden="true"></i> Branding</button>' : ''}<button type="button" class="btn btn-secondary" id="ss-refresh" aria-keyshortcuts="Alt+R"><i class="fas fa-rotate" aria-hidden="true"></i> Refresh</button></div></div>
      <div class="info-grid">${this._stat('fa-box-open', 'Offerings', this._data.catalog.length)}${this._stat('fa-diagram-project', 'Resources', this._data.dashboard?.resources?.length || 0)}${this._stat('fa-hourglass-half', 'Pending', this._data.requests.filter(item => item.state === 'requested').length)}${this._stat('fa-basket-shopping', 'Basket', this._data.basket.items.length, (this._data.basket.preview.compatibleActions || []).join(', '))}</div>
      <div class="tabs" role="tablist" aria-label="Self-service sections">${this._tabBtn('catalog', 'fa-store', this._t('tabs.catalog', 'Catalog'))}${this._tabBtn('project', 'fa-chart-pie', this._t('tabs.project', 'Project'))}${this._tabBtn('requests', 'fa-timeline', this._t('tabs.requests', 'Requests'))}${['admin','operator'].includes(App.user?.role) ? this._tabBtn('approvals', 'fa-user-check', `Approvals (${this._data.inbox.length})`) : ''}${this._tabBtn('basket', 'fa-basket-shopping', `Basket (${this._data.basket.items.length})`)}${this._tabBtn('incidents', 'fa-triangle-exclamation', `${this._t('tabs.incidents', 'Incidents')} (${this._data.incidents.length})`)}${this._tabBtn('guidance', 'fa-circle-question', this._t('tabs.guidance', 'Guidance'))}</div>
      <div id="ss-content" role="tabpanel" tabindex="0">${this._content()}</div></div>`;
    this._bind();
  },
  _content() { if (this._tab === 'project') return this._project(); if (this._tab === 'requests') return this._requests(); if (this._tab === 'approvals') return this._approvals(); if (this._tab === 'basket') return this._basket(); if (this._tab === 'incidents') return this._incidents(); if (this._tab === 'guidance') return this._guidance(); return this._catalog(); },
  _catalog() {
    const admin = App.user?.role === 'admin';
    return `<div class="page-actions" style="justify-content:flex-end;margin-bottom:12px">${admin ? '<button class="btn btn-secondary btn-sm" id="ss-new-item"><i class="fas fa-plus"></i> Offering</button>' : ''}</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:12px">${this._data.catalog.map(item => {
      const v = item.version; const configured = (v?.offering?.targets || []).some(target => target.configured); const requestable = item.kind === 'vm' && item.lifecycle === 'active' && v?.state === 'published' && configured && this._projectId;
      return `<div class="card" style="padding:16px;display:flex;flex-direction:column;gap:9px"><div style="display:flex;justify-content:space-between;gap:8px"><h3 style="margin:0"><i class="fas ${item.kind === 'vm' ? 'fa-desktop' : item.kind === 'application' ? 'fa-cubes' : 'fa-circle-nodes'}" style="color:var(--accent);margin-right:7px"></i>${Utils.escapeHtml(item.name)}</h3><span class="badge ${item.lifecycle === 'active' ? 'badge-success' : 'badge-warning'}">${item.lifecycle}</span></div><div class="text-xs text-muted">${Utils.escapeHtml(item.owner)} · ${item.kind}</div><p class="text-sm" style="margin:0;min-height:40px">${Utils.escapeHtml(item.description)}</p><div class="text-sm"><strong>Version:</strong> ${Utils.escapeHtml(v?.version || '—')} · <span class="mono text-xs">${Utils.escapeHtml((v?.versionHash || '').slice(0,12))}</span></div><div class="text-sm"><strong>Compatibility:</strong> ${Utils.escapeHtml((v?.compatibility?.providerTypes || v?.compatibility?.runtimes || []).join(', ') || 'workflow-defined')}</div>${!configured && item.kind === 'vm' ? '<div class="alert alert-warning text-xs" style="margin:0">Administrator target binding required.</div>' : ''}<div style="margin-top:auto"><button class="btn btn-primary btn-sm" data-ss-request="${item.slug}" ${requestable ? '' : 'disabled'}><i class="fas fa-paper-plane"></i> Request</button>${admin ? ` <button class="btn btn-secondary btn-sm" data-ss-version="${item.id}"><i class="fas fa-code-branch"></i> Versions</button>` : ''}</div></div>`;
    }).join('') || '<div class="empty-msg">No offerings available.</div>'}</div>`;
  },
  _project() {
    const d = this._data.dashboard; if (!d) return '<div class="empty-msg">Choose an accessible project.</div>';
    const quotas = Object.entries(d.quotas || {}).map(([metric, quota]) => `<tr><td>${Utils.escapeHtml(metric)}</td><td>${Number(d.usage[metric] || 0).toLocaleString()}</td><td>${quota.softLimit == null ? '—' : Number(quota.softLimit).toLocaleString()}</td><td>${quota.hardLimit == null ? '—' : Number(quota.hardLimit).toLocaleString()}</td><td><span class="badge ${quota.hardExceeded ? 'badge-danger' : quota.softExceeded ? 'badge-warning' : 'badge-success'}">${quota.hardExceeded ? 'hard exceeded' : quota.softExceeded ? 'soft exceeded' : 'within limit'}</span></td></tr>`).join('');
    const quotaRequests = (this._data.quotaRequests || []).map(item => `<tr><td>#${item.id}</td><td>${Object.entries(item.requestedLimits || {}).map(([metric, value]) => `${Utils.escapeHtml(metric)}: ${value.hardLimit ?? '—'}`).join('<br>')}</td><td>${Math.round(item.duration_seconds / 3600)}h</td><td><span class="badge ${this._badge(item.state)}">${item.state}</span><div class="text-xs text-muted">approval: ${item.approval_state}</div></td></tr>`).join('');
    const recommendations = (this._data.recommendations || []).map(item => `<article class="ss-recommendation card"><div><h4>${Utils.escapeHtml(item.title)}</h4><p class="text-sm">${Utils.escapeHtml(item.reason)}</p><div class="text-xs text-muted">Confidence ${Math.round(item.confidence.score * 100)}% · ${Utils.escapeHtml(item.confidence.basis)}</div></div><div><span class="badge badge-secondary">advisory</span> <button type="button" class="btn btn-xs btn-secondary" data-ss-recommendation="${Utils.escapeHtml(item.key)}" ${item.action.kind === 'none' ? 'disabled' : ''}>Review action</button></div><details><summary>Evidence, impact and undo</summary><pre class="mono text-xs">${Utils.escapeHtml(JSON.stringify(item.evidence, null, 2))}</pre><p class="text-sm"><strong>Impact:</strong> ${Utils.escapeHtml(item.impact)}</p><p class="text-sm"><strong>Undo:</strong> ${Utils.escapeHtml(item.undo)}</p></details></article>`).join('');
    return `${d.alerts?.length ? `<div class="alert alert-warning">${d.alerts.map(alert => Utils.escapeHtml(alert.message)).join('<br>')}</div>` : ''}<div class="card ss-scroll"><div class="card-header"><div><h3>${Utils.escapeHtml(d.project.name)}</h3><p class="text-muted text-sm">Quota posture and project inventory.</p></div><div class="page-actions"><button type="button" class="btn btn-secondary btn-sm" id="ss-quota-request"><i class="fas fa-arrow-up" aria-hidden="true"></i> ${this._t('requestQuota', 'Request quota')}</button>${App.user?.role === 'admin' ? '<button type="button" class="btn btn-secondary btn-sm" id="ss-policy"><i class="fas fa-shield" aria-hidden="true"></i> Policy</button>' : ''}</div></div><table class="data-table"><thead><tr><th>Metric</th><th>Usage</th><th>Soft</th><th>Hard</th><th>Posture</th></tr></thead><tbody>${quotas || this._empty('No quotas configured', 5)}</tbody></table></div>
      <div class="card ss-scroll" style="margin-top:12px"><div class="card-header"><div><h3>Temporary quota requests</h3><p class="text-muted text-sm">Every increase is approval-bound and expires automatically.</p></div></div><table class="data-table"><thead><tr><th>ID</th><th>Limits</th><th>Duration</th><th>State</th></tr></thead><tbody>${quotaRequests || this._empty('No quota increase requests', 4)}</tbody></table></div>
      <section aria-labelledby="ss-recommendations-title" style="margin-top:12px"><h3 id="ss-recommendations-title">Explainable recommendations</h3><div class="ss-recommendation-grid">${recommendations}</div></section>
      <div class="card ss-scroll" style="margin-top:12px"><div class="card-header"><div><h3>Project resources</h3><p class="text-muted text-sm">Use Arrow Left/Right between operations; Enter opens the guarded confirmation.</p></div></div><table class="data-table"><thead><tr><th>Resource</th><th>Type / endpoint</th><th>Capacity</th><th>Policy actions</th></tr></thead><tbody>${d.resources.map(r => `<tr><td><strong>${Utils.escapeHtml(r.displayName)}</strong><div class="mono text-xs">${Utils.escapeHtml(r.resourceKey)}</div></td><td>${Utils.escapeHtml(r.resourceType)} · ${r.providerHostId || 'unbound'}</td><td class="text-xs">${Number(r.cpuMillicores || 0)/1000} vCPU · ${Utils.formatBytes(r.memoryBytes || 0)} · ${Utils.formatBytes(r.storageBytes || 0)}</td><td class="ss-operation-group" role="group" aria-label="Operations for ${Utils.escapeHtml(r.displayName)}">${['start','shutdown','reboot','snapshot','console'].map(action => `<button type="button" class="btn btn-xs btn-secondary" data-ss-lifecycle="${r.id}" data-ss-op data-action="${action}" aria-label="${this._t(`actions.${action}`, action)} ${Utils.escapeHtml(r.displayName)}" aria-keyshortcuts="Enter Space" ${/^ddr_vm_[a-f0-9]{26}$/.test(r.resourceKey) && r.providerHostId ? '' : 'disabled'}>${this._t(`actions.${action}`, action)}</button>`).join(' ')}</td></tr>`).join('') || this._empty('No resources assigned', 4)}</tbody></table></div><div class="alert alert-info text-sm" style="margin-top:12px">${Utils.escapeHtml(d.cost.message)}</div>`;
  },
  _requests() { return `<div class="card ss-scroll"><div class="card-header"><div><h3>Fulfillment timeline</h3><p class="text-muted text-sm">Requested → approved → running → validated.</p></div></div><table class="data-table"><thead><tr><th>Request</th><th>Action</th><th>Risk / cost</th><th>State</th><th></th></tr></thead><tbody>${this._data.requests.map(r => `<tr><td><strong class="mono">${Utils.escapeHtml(r.requestKey)}</strong><div class="text-xs text-muted">${new Date(r.createdAt).toLocaleString()} · ${Utils.escapeHtml(r.requesterUsername || String(r.requestedBy))}</div></td><td>${Utils.escapeHtml(r.requestKind)} · ${Utils.escapeHtml(r.actionKey)}</td><td>R${r.risk}<div class="text-xs">${this._money(r.costPreview)}</div></td><td><span class="badge ${this._badge(r.state)}">${r.state}</span></td><td><button type="button" class="btn btn-xs btn-secondary" data-ss-timeline="${r.id}">Timeline</button> <button type="button" class="btn btn-xs btn-secondary" data-ss-troubleshoot="${r.id}">Troubleshoot</button>${r.state === 'approved' && ['admin','operator'].includes(App.user?.role) ? ` <button type="button" class="btn btn-xs btn-primary" data-ss-fulfill="${r.id}">Fulfill</button>` : ''}</td></tr>`).join('') || this._empty('No requests yet', 5)}</tbody></table></div>`; },
  _approvals() { return `<div class="card" style="overflow:auto"><div class="card-header"><div><h3>Approval inbox</h3><p class="text-muted text-sm">Risk, diff, cost and expiry stay bound to the approval hash.</p></div></div><table class="data-table"><thead><tr><th>Request</th><th>Context</th><th>Expiry</th><th>Decision</th></tr></thead><tbody>${this._data.inbox.map(r => `<tr><td><strong class="mono">${Utils.escapeHtml(r.requestKey)}</strong><div class="text-xs">${Utils.escapeHtml(r.requesterUsername || '')}</div></td><td>${Utils.escapeHtml(r.actionKey)} · R${r.risk}<div class="text-xs">${this._money(r.costPreview)} · <button class="btn btn-xs btn-secondary" data-ss-timeline="${r.id}">diff</button></div></td><td>${new Date(r.expiresAt).toLocaleString()}</td><td><button class="btn btn-xs btn-success" data-ss-decide="${r.id}" data-decision="approve">Approve</button> <button class="btn btn-xs btn-danger" data-ss-decide="${r.id}" data-decision="reject">Reject</button></td></tr>`).join('') || this._empty('No requests await approval', 4)}</tbody></table></div>`; },
  _basket() { const b = this._data.basket; return `<div class="card" style="overflow:auto"><div class="card-header"><div><h3>Cross-page selection basket</h3><p class="text-muted text-sm">Selections persist server-side; compatibility is recalculated before bulk work.</p></div>${b.items.length ? '<button class="btn btn-secondary btn-sm" id="ss-basket-clear"><i class="fas fa-trash"></i> Clear</button>' : ''}</div>${b.preview.blockers.length ? `<div class="alert alert-warning" style="margin:12px">${b.preview.blockers.map(item => Utils.escapeHtml(item.message)).join('<br>')}</div>` : ''}<div style="padding:0 15px 12px" class="text-sm"><strong>Compatible actions:</strong> ${b.preview.compatibleActions.map(action => `<span class="badge badge-secondary">${action}</span>`).join(' ') || 'none'}</div><table class="data-table"><thead><tr><th>Resource</th><th>Kind</th><th>Endpoint</th><th></th></tr></thead><tbody>${b.items.map(item => `<tr><td><strong>${Utils.escapeHtml(item.displayName)}</strong><div class="mono text-xs">${Utils.escapeHtml(item.resourceRef)}</div></td><td>${item.resourceKind}</td><td>${item.hostId || 'current'}</td><td><button class="action-btn danger" data-ss-basket-remove="${item.id}" title="Remove"><i class="fas fa-times"></i></button></td></tr>`).join('') || this._empty('Add resources from VM or container pages', 4)}</tbody></table></div>`; },
  _incidents() {
    return `<div class="alert alert-info text-sm"><strong>${this._t('safety.mobile', 'Safe mobile view:')}</strong> read status, acknowledge or pause personal notifications. No destructive infrastructure action is exposed.</div><div class="ss-incident-grid">${this._data.incidents.map(item => `<article class="card ss-incident" data-severity="${item.severity}"><div class="ss-incident-head"><div><span class="badge ${item.severity === 'critical' ? 'badge-danger' : item.severity === 'warning' ? 'badge-warning' : 'badge-secondary'}">${item.severity}</span> <strong>${Utils.escapeHtml(item.title)}</strong></div><span class="badge ${this._badge(item.state)}">${item.state}</span></div>${item.projectName ? `<div class="text-xs text-muted">${Utils.escapeHtml(item.projectName)}</div>` : ''}${item.summary ? `<p class="text-sm">${Utils.escapeHtml(item.summary)}</p>` : ''}${item.jobStatus ? `<div class="text-sm"><strong>Job:</strong> ${Utils.escapeHtml(item.jobStatus.state)} · <span class="mono text-xs">${Utils.escapeHtml(item.jobStatus.operationId)}</span></div>` : ''}<div class="text-xs text-muted">Updated ${new Date(item.updatedAt).toLocaleString()}</div>${item.pausedUntil ? `<div class="text-xs text-muted">Paused until ${new Date(item.pausedUntil).toLocaleString()}</div>` : ''}<div class="ss-incident-actions"><button type="button" class="btn btn-xs btn-secondary" data-ss-incident="${Utils.escapeHtml(item.key)}" data-action="acknowledge" ${item.acknowledgedAt ? 'disabled' : ''}><i class="fas fa-check" aria-hidden="true"></i> ${this._t('acknowledge', 'Acknowledge')}</button><button type="button" class="btn btn-xs btn-secondary" data-ss-incident="${Utils.escapeHtml(item.key)}" data-action="pause_notifications"><i class="fas fa-bell-slash" aria-hidden="true"></i> ${this._t('pause', 'Pause notifications')}</button></div></article>`).join('') || '<div class="empty-msg">No active incidents or running jobs.</div>'}</div>`;
  },
  _guidance() {
    const help = this._data.help;
    return `<div class="ss-guidance-grid"><section class="card" aria-labelledby="ss-help-title"><div class="card-header"><div><h3 id="ss-help-title">Contextual provider guidance</h3><p class="text-muted text-sm">Provider, version and action caveats with a next safe test.</p></div></div><div class="ss-guidance-form"><label for="ss-help-provider">Provider</label><select id="ss-help-provider" class="form-control"><option>proxmox</option><option>vsphere</option><option>xen</option><option>incus</option><option>kubernetes</option><option>nomad</option><option>docker</option></select><label for="ss-help-version">Version</label><input id="ss-help-version" class="form-control" maxlength="80" placeholder="for example 8.3"><label for="ss-help-action">Action</label><select id="ss-help-action" class="form-control"><option value="provision">provision</option><option value="start">start</option><option value="shutdown">shutdown</option><option value="reboot">reboot</option><option value="snapshot">snapshot</option><option value="console">console</option></select><button type="button" class="btn btn-primary" id="ss-help-load">Load guidance</button></div><div id="ss-help-results" aria-live="polite">${help ? this._helpHtml(help) : '<div class="empty-msg">Choose a context to load guidance.</div>'}</div></section>
      <section class="card" aria-labelledby="ss-feedback-title"><div class="card-header"><div><h3 id="ss-feedback-title">Product feedback counters</h3><p class="text-muted text-sm">Explicit opt-in, daily local aggregates, no network transmission.</p></div><button type="button" class="btn btn-secondary btn-sm" id="ss-feedback-settings">Configure</button></div><div style="padding:14px"><span class="badge ${this._data.feedback?.preference?.enabled ? 'badge-success' : 'badge-secondary'}">${this._data.feedback?.preference?.enabled ? 'opted in' : 'off by default'}</span><pre class="mono text-xs ss-payload-preview">${Utils.escapeHtml(JSON.stringify(this._data.feedback?.payload?.sampleCounter || {}, null, 2))}</pre><p class="text-xs text-muted">Excluded: ${Utils.escapeHtml((this._data.feedback?.payload?.excluded || []).join(', '))}</p></div></section></div>`;
  },
  _helpHtml(help) {
    const version = help.context?.versionGuidance || {};
    return `<div class="alert alert-info text-sm" style="margin:12px">${Utils.escapeHtml(version.testedFamily || '')} · ${Utils.escapeHtml(version.note || '')}<br><strong>Evaluated:</strong> ${Utils.escapeHtml(version.evaluatedVersion || '')}</div>${(help.topics || []).map(topic => `<article class="ss-help-topic"><h4>${Utils.escapeHtml(topic.title)}</h4><p class="text-sm">${Utils.escapeHtml(topic.summary)}</p><ul>${topic.caveats.map(item => `<li>${Utils.escapeHtml(item)}</li>`).join('')}</ul><div class="alert alert-success text-sm"><strong>Next safe test:</strong> ${Utils.escapeHtml(topic.nextSafeTest)}</div></article>`).join('') || '<div class="empty-msg">No exact topic matched this context.</div>'}`;
  },
  _bind() {
    this._container.querySelector('#ss-refresh')?.addEventListener('click', () => this._refresh());
    this._container.querySelector('#ss-project')?.addEventListener('change', async e => { this._projectId = Number(e.target.value); await this._loadProjectContext(); this._applyBranding(); this._paint(); });
    this._container.querySelectorAll('[data-ss-tab]').forEach(b => b.addEventListener('click', () => { this._tab = b.dataset.ssTab; if (this._tab === 'incidents') this._feedback('incident.view'); this._paint(); }));
    this._container.querySelectorAll('[data-ss-request]').forEach(b => b.addEventListener('click', () => this._request(this._data.catalog.find(item => item.slug === b.dataset.ssRequest))));
    this._container.querySelectorAll('[data-ss-version]').forEach(b => b.addEventListener('click', () => this._versions(Number(b.dataset.ssVersion))));
    this._container.querySelector('#ss-new-item')?.addEventListener('click', () => this._newItem());
    this._container.querySelector('#ss-policy')?.addEventListener('click', () => this._policy());
    this._container.querySelector('#ss-quota-request')?.addEventListener('click', () => this._quotaRequest());
    this._container.querySelector('#ss-branding')?.addEventListener('click', () => this._branding());
    this._container.querySelectorAll('[data-ss-lifecycle]').forEach(b => b.addEventListener('click', () => this._lifecycle(Number(b.dataset.ssLifecycle), b.dataset.action)));
    this._container.querySelectorAll('[data-ss-timeline]').forEach(b => b.addEventListener('click', () => this._timeline(Number(b.dataset.ssTimeline))));
    this._container.querySelectorAll('[data-ss-decide]').forEach(b => b.addEventListener('click', () => this._decide(Number(b.dataset.ssDecide), b.dataset.decision)));
    this._container.querySelectorAll('[data-ss-fulfill]').forEach(b => b.addEventListener('click', () => this._fulfill(Number(b.dataset.ssFulfill))));
    this._container.querySelectorAll('[data-ss-troubleshoot]').forEach(b => b.addEventListener('click', () => this._troubleshoot(Number(b.dataset.ssTroubleshoot))));
    this._container.querySelectorAll('[data-ss-recommendation]').forEach(b => b.addEventListener('click', () => this._followRecommendation(b.dataset.ssRecommendation)));
    this._container.querySelectorAll('[data-ss-incident]').forEach(b => b.addEventListener('click', () => this._incidentAction(b.dataset.ssIncident, b.dataset.action)));
    this._container.querySelector('#ss-help-load')?.addEventListener('click', () => this._loadHelp());
    this._container.querySelector('#ss-feedback-settings')?.addEventListener('click', () => this._feedbackSettings());
    this._container.querySelectorAll('[data-ss-basket-remove]').forEach(b => b.addEventListener('click', async () => { try { this._data.basket = await Api.removeSelfServiceBasketItem(Number(b.dataset.ssBasketRemove)); this._paint(); } catch (e) { Toast.error(e.message); } }));
    this._container.querySelector('#ss-basket-clear')?.addEventListener('click', async () => { this._data.basket = await Api.clearSelfServiceBasket(); this._paint(); });
    this._bindKeyboard();
  },
  _bindKeyboard() {
    const tabs = [...this._container.querySelectorAll('[role="tab"]')];
    tabs.forEach((tab, index) => tab.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return; event.preventDefault();
      const target = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
      tabs[target].focus(); tabs[target].click();
    }));
    this._container.querySelectorAll('.ss-operation-group').forEach(group => group.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return; const buttons = [...group.querySelectorAll('[data-ss-op]:not(:disabled)')];
      const index = buttons.indexOf(document.activeElement); if (index < 0) return; event.preventDefault();
      buttons[(index + (event.key === 'ArrowRight' ? 1 : -1) + buttons.length) % buttons.length].focus();
    }));
    if (this._keyboardHandler) this._container.removeEventListener('keydown', this._keyboardHandler);
    this._keyboardHandler = event => { if (event.altKey && event.key.toLowerCase() === 'r') { event.preventDefault(); this._refresh(); } };
    this._container.addEventListener('keydown', this._keyboardHandler);
  },
  async _quotaRequest() {
    const current = this._data.dashboard?.quotas || {};
    const result = await Modal.form(`<div class="alert alert-info text-sm">Canonical units are used: millicores for CPU and bytes for memory/storage. The grant is time-bound and approval is always separate.</div><label class="form-label" for="ss-q-metric">Metric</label><select id="ss-q-metric" class="form-control">${['cpu_millicores','memory_bytes','storage_bytes','network_count','public_ip_count','snapshot_count','backup_count','gpu_count','device_count'].map(metric => `<option value="${metric}">${metric}</option>`).join('')}</select><label class="form-label" for="ss-q-soft">Requested soft limit</label><input id="ss-q-soft" type="number" min="0" class="form-control"><label class="form-label" for="ss-q-hard">Requested hard limit</label><input id="ss-q-hard" type="number" min="0" class="form-control"><label class="form-label" for="ss-q-hours">Duration (hours)</label><input id="ss-q-hours" type="number" min="1" max="720" value="24" class="form-control"><label class="form-label" for="ss-q-reason">Business reason</label><textarea id="ss-q-reason" maxlength="500" rows="3" class="form-control"></textarea>`, {
      title: this._t('requestQuota', 'Request temporary quota increase'), submitLabel: 'Submit for approval', width: '620px',
      onMount: root => { const update = () => { const metric = root.querySelector('#ss-q-metric').value; const quota = current[metric] || {}; root.querySelector('#ss-q-soft').value = quota.softLimit ?? ''; root.querySelector('#ss-q-hard').value = quota.hardLimit ?? ''; }; root.querySelector('#ss-q-metric').addEventListener('change', update); update(); },
      onSubmit: root => { const metric = root.querySelector('#ss-q-metric').value; const softLimit = Number(root.querySelector('#ss-q-soft').value); const hardLimit = Number(root.querySelector('#ss-q-hard').value); const hours = Number(root.querySelector('#ss-q-hours').value); const reason = root.querySelector('#ss-q-reason').value.trim(); if (!reason || !Number.isSafeInteger(softLimit) || !Number.isSafeInteger(hardLimit) || hardLimit < softLimit) { Toast.error('Provide valid limits, duration and reason'); return false; } return { limits: { [metric]: { softLimit, hardLimit } }, durationSeconds: hours * 3600, reason }; },
    });
    if (!result) return; try { await Api.requestQuota(this._projectId, result); Toast.success('Quota request submitted for approval'); this._announce('Quota request submitted'); await this._loadProjectContext(); this._paint(); } catch (error) { Toast.error(error.message); }
  },
  async _branding() {
    const branding = this._data.branding || {};
    const result = await Modal.form(`<label class="form-label" for="ss-b-name">Display name</label><input id="ss-b-name" class="form-control" maxlength="100" value="${Utils.escapeHtml(branding.displayName || '')}"><label class="form-label" for="ss-b-logo">Logo URL (same-origin path or HTTPS)</label><input id="ss-b-logo" class="form-control" maxlength="500" value="${Utils.escapeHtml(branding.logoUrl || '')}"><label class="form-label" for="ss-b-color">Accent color</label><input id="ss-b-color" type="color" class="form-control" value="${Utils.escapeHtml(branding.accentColor || '#4f8cff')}"><label class="form-label" for="ss-b-support">Support URL</label><input id="ss-b-support" class="form-control" maxlength="500" value="${Utils.escapeHtml(branding.supportUrl || '')}"><label class="form-label" for="ss-b-help">Help URL</label><input id="ss-b-help" class="form-control" maxlength="500" value="${Utils.escapeHtml(branding.helpUrl || '')}"><label><input id="ss-b-project" type="checkbox" ${this._projectId ? 'checked' : ''}> Apply only to the selected project</label>`, {
      title: 'Portal branding', submitLabel: 'Save branding', onSubmit: root => ({ projectId: root.querySelector('#ss-b-project').checked ? this._projectId : null, displayName: root.querySelector('#ss-b-name').value, logoUrl: root.querySelector('#ss-b-logo').value, accentColor: root.querySelector('#ss-b-color').value, supportUrl: root.querySelector('#ss-b-support').value, helpUrl: root.querySelector('#ss-b-help').value }),
    });
    if (!result) return; try { const saved = await Api.saveSelfServiceBranding(result); this._data.branding = saved.branding; this._applyBranding(); Toast.success('Branding saved'); this._paint(); } catch (error) { Toast.error(error.message); }
  },
  async _loadHelp() {
    try {
      const providerType = this._container.querySelector('#ss-help-provider').value; const providerVersion = this._container.querySelector('#ss-help-version').value; const action = this._container.querySelector('#ss-help-action').value;
      this._data.help = await Api.getSelfServiceContextualHelp({ projectId: this._projectId, providerType, providerVersion, action });
      const target = this._container.querySelector('#ss-help-results'); if (target) target.innerHTML = this._helpHtml(this._data.help);
      this._feedback('help.view', 'success', providerType); this._announce('Contextual guidance loaded');
    } catch (error) { Toast.error(error.message); }
  },
  async _troubleshoot(requestId) {
    try {
      const { session } = await Api.createSelfServiceTroubleshooting(requestId);
      const copied = await Modal.form(`<div class="alert alert-info text-sm">Bundle hash <span class="mono">${session.bundleHash}</span>. Request values, resource references, users, URLs, credentials and raw errors are excluded.</div><ol class="ss-checklist">${session.checklist.map(item => `<li data-status="${item.status}"><strong>${Utils.escapeHtml(item.key)}</strong> · ${Utils.escapeHtml(item.status)}<div class="text-sm">${Utils.escapeHtml(item.evidence)}</div></li>`).join('')}</ol><div class="alert alert-success text-sm"><strong>Next safe test:</strong> ${Utils.escapeHtml(session.nextSafeTest.label)}</div><textarea id="ss-support-bundle" class="form-control mono text-xs" rows="12" readonly>${Utils.escapeHtml(JSON.stringify(session.supportBundle, null, 2))}</textarea>`, { title: `Troubleshooting ${session.key}`, submitLabel: 'Copy support bundle', width: '760px', onSubmit: root => root.querySelector('#ss-support-bundle').value });
      if (copied) { await Utils.copyToClipboard(copied); Toast.success('Privacy-safe support bundle copied'); }
      this._feedback('troubleshooting.complete');
    } catch (error) { Toast.error(error.message); this._feedback('request.failure', 'failure'); }
  },
  async _incidentAction(key, action) {
    try {
      let body = { action };
      if (action === 'pause_notifications') {
        const result = await Modal.form('<label class="form-label" for="ss-inc-minutes">Pause minutes</label><input id="ss-inc-minutes" type="number" min="5" max="1440" value="30" class="form-control"><label class="form-label" for="ss-inc-note">Note</label><textarea id="ss-inc-note" maxlength="240" class="form-control"></textarea>', { title: 'Pause personal notifications', submitLabel: 'Pause', onSubmit: root => ({ action, minutes: Number(root.querySelector('#ss-inc-minutes').value), note: root.querySelector('#ss-inc-note').value }) });
        if (!result) return; body = result;
      }
      await Api.updateSelfServiceIncident(key, body); const incidents = await Api.getSelfServiceIncidents(); this._data.incidents = incidents.incidents || [];
      this._feedback('incident.acknowledge'); this._announce(action === 'acknowledge' ? 'Incident acknowledged' : 'Incident notifications paused'); this._paint();
    } catch (error) { Toast.error(error.message); }
  },
  async _feedbackSettings() {
    const current = this._data.feedback?.preference || {};
    const result = await Modal.form(`<div class="alert alert-info text-sm">No network transmission. Only allowlisted daily counters are stored locally; payloads, resource names and error text are excluded.</div><label><input id="ss-f-enabled" type="checkbox" ${current.enabled ? 'checked' : ''}> Opt in to product feedback counters</label><label style="display:block;margin-top:8px"><input id="ss-f-usage" type="checkbox" ${current.usageEnabled !== false ? 'checked' : ''}> Usage funnel counters</label><label style="display:block;margin-top:8px"><input id="ss-f-failure" type="checkbox" ${current.failureEnabled !== false ? 'checked' : ''}> Failure funnel counters</label><pre class="mono text-xs ss-payload-preview">${Utils.escapeHtml(JSON.stringify(this._data.feedback?.payload?.sampleCounter || {}, null, 2))}</pre>`, { title: 'Product feedback privacy', submitLabel: 'Save preference', onSubmit: root => ({ enabled: root.querySelector('#ss-f-enabled').checked, usageEnabled: root.querySelector('#ss-f-usage').checked, failureEnabled: root.querySelector('#ss-f-failure').checked }) });
    if (!result) return; try { this._data.feedback = await Api.saveSelfServiceFeedbackPreference(result); Toast.success(this._data.feedback.preference.enabled ? 'Feedback counters enabled' : 'Feedback counters disabled'); this._paint(); } catch (error) { Toast.error(error.message); }
  },
  async _followRecommendation(key) {
    const item = (this._data.recommendations || []).find(entry => entry.key === key); if (!item) return;
    this._feedback('recommendation.follow');
    if (item.action.kind === 'quota_request') return this._quotaRequest();
    if (item.action.kind === 'troubleshoot') return this._troubleshoot(item.action.requestId);
    if (item.action.kind === 'open_approval_inbox') { this._tab = 'approvals'; this._paint(); }
  },
  async _feedback(eventKey, outcome = 'success', providerType = 'unknown') {
    try { await Api.recordSelfServiceFeedback({ eventKey, outcome, providerType }); } catch { /* feedback must never block user flow */ }
  },
  _field(field) {
    const visibility = field.visibleWhen ? ` data-visible-field="${field.visibleWhen.field}" data-visible-equals="${Utils.escapeHtml(String(field.visibleWhen.equals))}"` : '';
    let input = `<input class="form-control" data-form-key="${field.key}" data-form-type="${field.type}" type="${field.type === 'integer' ? 'number' : 'text'}" value="${Utils.escapeHtml(String(field.default ?? ''))}">`;
    if (field.type === 'enum') input = `<select class="form-control" data-form-key="${field.key}" data-form-type="enum">${field.options.map(value => `<option value="${Utils.escapeHtml(String(value))}"${value === field.default ? ' selected' : ''}>${Utils.escapeHtml(String(value))}</option>`).join('')}</select>`;
    if (field.type === 'boolean') input = `<label><input data-form-key="${field.key}" data-form-type="boolean" type="checkbox" ${field.default ? 'checked' : ''}> Enabled</label>`;
    return `<div class="form-group" data-form-row="${field.key}"${visibility}><label class="form-label">${Utils.escapeHtml(field.label || field.key)}${field.required ? ' *' : ''}</label>${input}</div>`;
  },
  async _request(item) {
    if (!item) return; const fields = item.version.formSchema.fields || [];
    const form = await Modal.form(`${fields.map(field => this._field(field)).join('')}<label class="form-label">Business reason *</label><textarea id="ss-reason" class="form-control" rows="3"></textarea><div id="ss-preview" class="alert alert-info text-sm" style="margin-top:12px">Complete the form for validation, quota and cost preview.</div>`, {
      title: `Request ${item.name} · v${item.version.version}`, submitLabel: 'Submit request', width: '640px', onMount: root => {
        const values = () => Object.fromEntries([...root.querySelectorAll('[data-form-key]')].filter(input => input.closest('[data-form-row]').style.display !== 'none').map(input => [input.dataset.formKey, input.dataset.formType === 'boolean' ? input.checked : input.dataset.formType === 'integer' ? Number(input.value) : input.value]));
        const update = Utils.debounce(async () => { root.querySelectorAll('[data-visible-field]').forEach(row => { const src = root.querySelector(`[data-form-key="${row.dataset.visibleField}"]`); row.style.display = String(src?.dataset.formType === 'boolean' ? src.checked : src?.value) === row.dataset.visibleEquals ? '' : 'none'; }); try { const p = await Api.previewSelfServiceCatalogRequest(item.slug, { tenantId: this._projectId, values: values() }); root.querySelector('#ss-preview').innerHTML = `<strong>${this._money(p.evaluation.costPreview)}</strong><br>${p.requestable ? 'Validation and hard-quota precheck passed.' : p.blockers.map(x => Utils.escapeHtml(x.message || x.code)).join('<br>')}`; if (!root._previewRecorded) { root._previewRecorded = true; this._feedback('request.preview', p.requestable ? 'success' : 'failure', item.version?.offering?.targets?.[0]?.providerType || 'unknown'); } } catch (e) { root.querySelector('#ss-preview').textContent = e.message; } }, 250);
        root.querySelectorAll('[data-form-key]').forEach(input => input.addEventListener('input', update)); root._values = values; update();
      }, onSubmit: root => { const reason = root.querySelector('#ss-reason').value.trim(); if (!reason) { Toast.error('Business reason is required'); return false; } return { values: root._values(), reason }; },
    });
    if (!form) return; const provider = item.version?.offering?.targets?.[0]?.providerType || 'unknown'; try { const r = await Api.createSelfServiceCatalogRequest(item.slug, { tenantId: this._projectId, ...form }); this._feedback('request.submit', 'success', provider); Toast.success(`Request ${r.request.requestKey} created`); await this._refresh(); } catch (e) { this._feedback('request.failure', 'failure', provider); Toast.error(e.message); }
  },
  async _lifecycle(resourceId, action) {
    const result = await Modal.form(`<div class="alert alert-info text-sm">${Utils.escapeHtml(action)} is checked against project policy and durable identity.</div>${action === 'snapshot' ? '<label class="form-label">Snapshot name</label><input id="ss-snapshot" class="form-control" value="before-change">' : ''}<label class="form-label" style="margin-top:10px">Reason *</label><textarea id="ss-life-reason" class="form-control"></textarea>`, { title: `${action} lifecycle request`, submitLabel: action === 'console' ? 'Authorize console' : 'Submit for approval', onSubmit: root => { const reason = root.querySelector('#ss-life-reason').value.trim(); if (!reason) { Toast.error('Reason is required'); return false; } return { reason, snapshotName: root.querySelector('#ss-snapshot')?.value }; } });
    if (!result) return; try { const r = await Api.createSelfServiceLifecycleRequest(this._projectId, resourceId, { action, ...result }); Toast.success(`Request ${r.request.state}`); await this._refresh(); if (action === 'console') this._timeline(r.request.id); } catch (e) { Toast.error(e.message); }
  },
  async _timeline(id) {
    try { const { request: r } = await Api.getSelfServiceRequest(id); await Modal.confirm(`<div class="info-grid" style="margin-bottom:12px">${this._stat('fa-shield', 'Risk', `R${r.risk}`)}${this._stat('fa-coins', 'Estimate', this._money(r.costPreview))}${this._stat('fa-hourglass', 'State', r.state)}</div><div class="card" style="padding:12px;margin-bottom:12px"><strong>Normalized diff</strong><pre class="mono text-xs" style="white-space:pre-wrap">${Utils.escapeHtml(JSON.stringify(r.diff,null,2))}</pre></div><div style="display:grid;gap:8px">${r.events.map(e => `<div class="card" style="padding:10px;border-left:3px solid var(--accent)"><strong>${e.sequence}. ${Utils.escapeHtml(e.type)}</strong> <span class="badge ${this._badge(e.state)}">${e.state}</span><div class="text-sm">${Utils.escapeHtml(e.message)}</div><div class="text-xs text-muted">${new Date(e.createdAt).toLocaleString()}</div>${e.evidence?.url ? `<a class="btn btn-xs btn-primary" href="${Utils.escapeHtml(e.evidence.url)}">Open console</a>` : ''}</div>`).join('')}</div>`, { title: r.requestKey, confirmText: 'Close', html: true, width: '760px' }); } catch (e) { Toast.error(e.message); }
  },
  async _decide(id, decision) { const result = await Modal.form('<label class="form-label">Decision comment</label><textarea id="ss-decision-comment" class="form-control" rows="3" maxlength="500"></textarea>', { title: `${decision} request`, submitLabel: decision === 'approve' ? 'Approve' : 'Reject', onSubmit: root => ({ comment: root.querySelector('#ss-decision-comment').value.trim() }) }); if (!result) return; try { await Api.decideSelfServiceRequest(id, { decision, comment: result.comment }); Toast.success(`Request ${decision}d`); await this._refresh(); } catch (e) { Toast.error(e.message); } },
  async _fulfill(id) {
    try { const p = await Api.preflightSelfServiceFulfillment(id); const plan = p.plan; const ok = await Modal.confirm(`${plan.blockers?.length ? `<div class="alert alert-danger">${plan.blockers.map(x => Utils.escapeHtml(x.reason)).join('<br>')}</div>` : ''}<div class="card" style="padding:12px"><strong>Provider:</strong> ${Utils.escapeHtml(p.target.providerType)}<br><strong>Plan hash:</strong> <span class="mono text-xs">${plan.planHash}</span><br><strong>Valid until:</strong> ${new Date(plan.validUntil).toLocaleString()}</div>`, { title: 'Fulfillment preflight', confirmText: 'Submit durable operation', danger: plan.confirmation?.mode === 'typed_name', typeToConfirm: plan.confirmation?.mode === 'typed_name' ? plan.confirmation.expected : null, html: true, width: '660px' }); if (!ok || !plan.allowed) return; const key = `self-service-${id}-${globalThis.crypto?.randomUUID?.() || Date.now()}`; const r = await Api.fulfillSelfServiceRequest(id, { planHash: plan.planHash, confirm: true, confirmName: plan.confirmation?.expected, idempotencyKey: key }); Toast.success(`Operation ${r.request.providerOperationId} queued`); await this._refresh(); } catch (e) { Toast.error(e.message); }
  },
  async _policy() {
    try { const { policy: p } = await Api.getSelfServiceProjectPolicy(this._projectId); const r = await Modal.form(`<label class="form-label">Allowed offering slugs (empty = all)</label><input id="ss-p-items" class="form-control" value="${Utils.escapeHtml(p.allowedItemSlugs.join(', '))}"><label class="form-label" style="margin-top:8px">Allowed lifecycle actions</label><input id="ss-p-actions" class="form-control" value="${Utils.escapeHtml(p.allowedActions.join(', '))}"><label class="form-label" style="margin-top:8px">Maximum risk</label><input id="ss-p-risk" type="number" min="1" max="4" class="form-control" value="${p.maximumRisk}"><label style="display:flex;gap:8px;margin-top:10px"><input id="ss-p-approval" type="checkbox" ${p.requireApproval ? 'checked' : ''}> Require approval</label>`, { title: 'Project self-service policy', submitLabel: 'Save', onSubmit: root => ({ allowedItemSlugs: root.querySelector('#ss-p-items').value.split(',').map(x => x.trim()).filter(Boolean), allowedActions: root.querySelector('#ss-p-actions').value.split(',').map(x => x.trim()).filter(Boolean), maximumRisk: Number(root.querySelector('#ss-p-risk').value), requireApproval: root.querySelector('#ss-p-approval').checked }) }); if (!r) return; await Api.saveSelfServiceProjectPolicy(this._projectId, r); Toast.success('Policy saved'); await this._refresh(); } catch (e) { Toast.error(e.message); }
  },
  async _newItem() {
    const r = await Modal.form('<label class="form-label">Slug</label><input id="ss-i-slug" class="form-control"><label class="form-label">Name</label><input id="ss-i-name" class="form-control"><label class="form-label">Kind</label><select id="ss-i-kind" class="form-control"><option value="vm">VM</option><option value="application">Application</option><option value="cluster">Cluster</option></select><label class="form-label">Owner</label><input id="ss-i-owner" class="form-control"><label class="form-label">Description</label><textarea id="ss-i-desc" class="form-control"></textarea>', { title: 'New offering', submitLabel: 'Create', onSubmit: root => ({ slug: root.querySelector('#ss-i-slug').value, name: root.querySelector('#ss-i-name').value, kind: root.querySelector('#ss-i-kind').value, owner: root.querySelector('#ss-i-owner').value, description: root.querySelector('#ss-i-desc').value }) }); if (!r) return; try { await Api.createSelfServiceCatalogItem(r); Toast.success('Offering created'); await this._refresh(); } catch (e) { Toast.error(e.message); }
  },
  async _versions(itemId) {
    try { const d = await Api.getSelfServiceCatalogItem(String(itemId), true); const current = d.item.version || {}; const r = await Modal.form(`<div style="margin-bottom:12px">${d.versions.map(v => `<div class="card" style="padding:8px;margin:5px 0"><strong>v${v.version}</strong> <span class="badge ${v.state === 'published' ? 'badge-success' : 'badge-secondary'}">${v.state}</span> · <span class="mono text-xs">${v.versionHash.slice(0,16)}</span></div>`).join('')}</div><label class="form-label">New semantic version</label><input id="ss-v-number" class="form-control"><label class="form-label">Changelog</label><textarea id="ss-v-log" class="form-control"></textarea>${[['form','Form schema',current.formSchema||{fields:[]}],['compat','Compatibility',current.compatibility||{}],['offering','Offering / private targets',current.management?.offering||{}],['cost','Cost model',current.costModel||{}]].map(([id,label,value]) => `<label class="form-label">${label} JSON</label><textarea id="ss-v-${id}" class="form-control mono" rows="5">${Utils.escapeHtml(JSON.stringify(value,null,2))}</textarea>`).join('')}`, { title: `${d.item.name} versions`, submitLabel: 'Create draft', width: '760px', onSubmit: root => { try { return { version: root.querySelector('#ss-v-number').value, changelog: root.querySelector('#ss-v-log').value, formSchema: JSON.parse(root.querySelector('#ss-v-form').value), compatibility: JSON.parse(root.querySelector('#ss-v-compat').value), offering: JSON.parse(root.querySelector('#ss-v-offering').value), costModel: JSON.parse(root.querySelector('#ss-v-cost').value) }; } catch { Toast.error('JSON is invalid'); return false; } } }); if (!r) return; const created = await Api.createSelfServiceCatalogVersion(itemId,r); const publish = await Modal.confirm(`Publish v${created.version.version} now?`, { title: 'Catalog lifecycle', confirmText: 'Publish' }); if (publish) await Api.transitionSelfServiceCatalogVersion(itemId,created.version.id,'published'); Toast.success(publish ? 'Version published' : 'Draft created'); await this._refresh(); } catch (e) { Toast.error(e.message); }
  },
};
